add_filter( 'woocommerce_show_page_title', 'perfectpixel_hide_archive_titles' );

function perfectpixel_hide_archive_titles( $show ) {
	if ( ( is_shop() && 'yes' === '{{hide_title_shop}}' )
		|| ( is_product_category() && 'yes' === '{{hide_title_categories}}' )
		|| ( is_product_tag() && 'yes' === '{{hide_title_tags}}' ) ) {
		return false;
	}
	return $show;
}
